<script>
  import ArcIcon from '../../components/ArcIcon.svelte'
  export let data; export let diagnostics = {}; export let diagnosticNode = ''; export let onDiagnostic
  let filter = 'all'
  $: nodes = data?.remnawave?.nodes || []
  $: visible = nodes.filter(n => filter === 'all' || (filter === 'online' ? n.connected : !n.connected))
</script>
<section class="page"><header><span>ИНФРАСТРУКТУРА</span><h2>Ноды ArcVPN</h2><p>Состояние, нагрузка, трафик и реальная диагностика узлов.</p></header>
  <nav><button class:active={filter==='all'} on:click={()=>filter='all'}>Все <i>{nodes.length}</i></button><button class:active={filter==='online'} on:click={()=>filter='online'}>Онлайн <i>{nodes.filter(n=>n.connected).length}</i></button><button class:active={filter==='problems'} on:click={()=>filter='problems'}>Проблемы <i>{nodes.filter(n=>!n.connected).length}</i></button></nav>
  <div class="nodes">{#each visible as node}<article class:off={!node.connected}><header><i>{node.country_code || '—'}</i><span><b>{node.name}</b><small>{node.address}</small></span><em>{node.connected?'ONLINE':'OFFLINE'}</em></header><div class="stats"><span><small>ОНЛАЙН</small><b>{node.users_online||0}</b></span><span><small>ТРАФИК</small><b>{node.traffic_used_gb||0} ГБ</b></span><span><small>RAM</small><b>{node.memory_used_pct||0}%</b></span><span><small>UPTIME</small><b>{Math.floor(Number(node.xray_uptime_seconds||0)/3600)} ч</b></span></div><div class="inbounds">{#each node.inbounds||[] as inbound}<span>{String(inbound.network||inbound.type||'').toUpperCase()} <b>:{inbound.port}</b></span>{/each}</div>{#if diagnostics[node.uuid]}<p class:good={diagnostics[node.uuid].ok}>{diagnostics[node.uuid].ok ? `Тест пройден за ${diagnostics[node.uuid].duration_ms} мс` : `Ошибка: ${diagnostics[node.uuid].error}`}</p>{/if}<button class="test" disabled={diagnosticNode===node.uuid} on:click={()=>onDiagnostic(node)}><ArcIcon name="pulse" size={16}/>{diagnosticNode===node.uuid?'Проверяем…':'Глубокий тест'}</button></article>{/each}</div>
</section>
